const tasks = await query('com.example.type.task');
print('total tasks:', tasks.length);
for (const t of tasks) {
  print(`${t.id} | status=${JSON.stringify(t.status)} | title=${JSON.stringify(t.title)}`);
}

const docsTasks = (await query('com.example.type.task'))
  .filter(t => /docs/i.test(t.title ?? ''));
print('matching "docs":', docsTasks.map(t => t.title));

for (const t of docsTasks) {
  update(t, (o) => { o.status = 'done'; });
}
await flush();

const after = await query('com.example.type.task');
const done = after.filter(t => t.status === 'done');
for (const t of after) print(`${t.status} | ${t.title}`);
print('done count:', done.length, 'of', after.length);

// check whether any other task-like types exist, to scope "in total"
const other = await ops["discovery-query-types"]({ query: "task" });
print('task-like types:', other.types.map(t => t.typename).join(', '));
